 readModel3DOutput(output: unknown): Model3DOutput | null {\n  const parsed = zModel3DNodeOutput.safeParse(output)\n  if (!parsed.success) return null\n  const { '3d': items, camera_info, model_3d_info, result } = parsed.data\n\n  const parsedItem = zModel3DItem.safeParse(items?.[0])\n  if (parsedItem.success) {\n    const item = parsedItem.data\n    return {\n      filePath: item.subfolder\n        ? `${item.subfolder}/${item.filename}`\n        : item.filename,\n      folder: item.type,\n      cameraState: parseOptional(zCameraState, camera_info?.[0]),\n      modelTransform: parseOptional(zModelTransform, model_3d_info?.[0])\n    }\n  }\n\n  const [filePath, cameraInfo, modelInfo] = result ?? []\n  if (typeof filePath !== 'string' || !filePath) return null\n  return {\n    filePath,\n    cameraState: parseOptional(zCameraState, cameraInfo),\n    modelTransform: parseOptional(\n      zModelTransform,\n      Array.isArray(modelInfo) ? modelInfo[0] : undefined\n    )\n  }\n}\n"],"mappings":"qIAeA,IAAM,EAAW,EAAS,CAAE,EAAG,EAAS,EAAG,EAAG,EAAS,EAAG,EAAG,EAAS,CAAE,CAAC,EAEnE,EAAc,EAAS,OAAO,CAAE,EAAG,EAAS,CAAE,CAAC,EAE/C,EAAe,EAAS,CAC5B,SAAU,EACV,OAAQ,EACR,KAAM,EAAS,EACf,WAAY,EAAO,CAAC,cAAe,cAAc,CAAC,EAClD,WAAY,EAAY,SAAS,EACjC,YAAa,EAAU,CAAC,CAAC,SAAS,EAClC,SAAU,EAAS,SAAS,EAC5B,IAAK,EAAS,CAAC,CAAC,SAAS,EACzB,OAAQ,EAAS,CAAC,CAAC,SAAS,EAC5B,KAAM,EAAS,CAAC,CAAC,SAAS,EAC1B,IAAK,EAAS,CAAC,CAAC,SAAS,EACzB,QAAS,EACC,CACN,KAAM,EAAS,EACf,MAAO,EAAS,EAChB,IAAK,EAAS,EACd,OAAQ,EAAS,CACnB,CAAC,CAAC,CACD,SAAS,CACd,CAAC,EAEK,EAAe,EAClB,GAAU,EAAa,UAAU,CAAK,CAAC,CAAC,OAC3C,EAEM,EAAkB,EAAS,CAC/B,SAAU,EACV,WAAY,EACZ,MAAO,CACT,CAAC,EAEK,EAAc,EAAO,CAAC,SAAU,MAAM,CAAC,EAEvC,EAAe,EAAS,CAC5B,SAAU,EAAS,CAAC,CAAC,IAAI,CAAC,EAC1B,UAAW,EAAS,CAAC,CAAC,SAAS,CAAC,CAAC,MAAM,IAAA,EAAS,EAChD,KAAM,EAAY,SAAS,CAAC,CAAC,MAAM,IAAA,EAAS,CAC9C,CAAC,EAEK,EAAgB,EAAQ,EAAU,CAAC,CAAC,CAAC,SAAS,CAAC,CAAC,MAAM,IAAA,EAAS,EAE/D,EAAqB,EAAS,CAClC,KAAM,EACN,YAAa,EACb,cAAe,EACf,OAAQ,CACV,CAAC,EAED,SAAS,cAAiB,EAAsB,EAA+B,CAC7E